233	function anlageFelder(db, d, alt = {}) {
234	  const has = (k) => Object.hasOwn(d, k);
235	  const f = {};
236	  if (has("name") || !alt.id) f.name = v.text(d.name, 120);
237	  if (has("typ") || !alt.id) f.typ = v.auswahl(d.typ, ANLAGE_TYPEN, alt.typ || "");
238	  if (has("status") || !alt.id) f.status = v.auswahl(d.status, ANLAGE_STATUS, alt.status || "betrieb");
239	  if (has("land") || !alt.id) f.land = v.auswahl(d.land, LAENDER, alt.land || "DE");
240	  const land = f.land || alt.land;
241	  if (has("bundesland") || !alt.id) f.bundesland = v.auswahl(d.bundesland, BUNDESLAENDER[land] || [], "");
242	  if (has("ort")) f.ort = v.text(d.ort, 80);
243	  for (const [k, max] of [["kwp", 500000], ["speicherKwh", 1000000], ["speicherKw", 500000], ["lastJahrKwh", 1e9]]) {
244	    if (has(k)) f[k] = v.zahl(d[k], { min: 0, max, stellen: 1 }) ?? 0;
245	  }
246	  if (has("wechselrichterAnzahl")) f.wechselrichterAnzahl = Math.round(v.zahl(d.wechselrichterAnzahl, { min: 1, max: 999 }) ?? 1);
247	  if (has("lastprofil") || !alt.id) f.lastprofil = v.auswahl(d.lastprofil, LASTPROFILE, alt.lastprofil || "gewerbe");
248	  if (has("inbetriebnahme")) f.inbetriebnahme = /^20\d\d-\d\d-\d\d$/.test(String(d.inbetriebnahme || "")) ? d.inbetriebnahme : "";
249	  if (has("beschreibung")) f.beschreibung = v.mehrzeilig(d.beschreibung, 2000);
250	  if (has("kundeId")) {
251	    const k = v.kennung(d.kundeId);
252	    if (k && !nutzerById(db, k)) throw ungueltig("Kundenkonto nicht gefunden.");
253	    f.kundeId = k || null;
254	  }
255	  if (has("organisationId")) {
256	    const o = v.kennung(d.organisationId);
257	    if (o && !(db.organisationen || []).some((x) => x.id === o)) throw ungueltig("Organisation nicht gefunden.");
258	    f.organisationId = o || null;
259	  }
260	  // Eigentum & Betrieb (Pflicht: Eigentümergesellschaft – ÖkoInvest GmbH oder Projektgesellschaft/SPV)
261	  if (has("eigentuemer") || !alt.id) f.eigentuemer = v.text(d.eigentuemer, 160);
262	  if (has("eigentuemerId")) {
263	    // Gesellschaftsverzeichnis (db.dienste.gesellschaften, Team Dienste): Kennung prüfen, Name übernehmen
264	    f.eigentuemerId = v.kennung(d.eigentuemerId) || null;
265	    if (f.eigentuemerId) {
266	      const g = (db.dienste?.gesellschaften || []).find((x) => x.id === f.eigentuemerId);
267	      if (!g) throw ungueltig("Gesellschaft nicht im Gesellschaftsverzeichnis gefunden.");
268	      f.eigentuemer = g.name;
269	    }
270	  }
271	  if (has("betriebsfuehrer") || !alt.id) f.betriebsfuehrer = v.text(d.betriebsfuehrer, 160) || alt.betriebsfuehrer || BETRIEBSFUEHRER_STANDARD;
272	  if (has("dachgeberIstKunde")) f.dachgeberIstKunde = v.wahr(d.dachgeberIstKunde);
273	  if (has("dachgeber")) f.dachgeber = v.text(d.dachgeber, 160);
274	  if (has("dienstbarkeitStatus")) f.dienstbarkeitStatus = v.auswahl(d.dienstbarkeitStatus, DIENSTBARKEIT_STATUS, "");
275	  if (has("dienstbarkeitDatum")) f.dienstbarkeitDatum = /^20\d\d-\d\d-\d\d$/.test(String(d.dienstbarkeitDatum || "")) ? d.dienstbarkeitDatum : "";
276	  if (has("dienstbarkeitDokumentId")) f.dienstbarkeitDokumentId = v.kennung(d.dienstbarkeitDokumentId) || null;
277	  if (has("dienstbarkeitHinweis")) f.dienstbarkeitHinweis = v.text(d.dienstbarkeitHinweis, 200);
