445	export async function zaehlerMonatswerte(n, anlageId) {
446	  const db = await lesenBereit();
447	  const a = anlageLaden(db, n, anlageId);
448	  const mps = db.anlagen.messpunkte.filter((m) => m.anlageId === a.id && m.abrechnungsrelevant);
449	  const gespeichert = db.anlagen.monatswerte.filter((m) => m.anlageId === a.id);
450	  const sim = a.simulation?.keineDaten ? [] : await zaehlerMonat(anlageAusgabe(db, n, a), { monate: 13 }).catch(() => []);
451	  const zeilen = [];
452	  for (const mp of mps) {
453	    for (const r of MESSPUNKT_ARTEN[mp.art]?.register || []) {
454	      const feld = mp.art === "erzeugung" ? "erzeugungKwh" : mp.art === "zweirichtung" ? (r.id === "1.8.0" ? "netzbezugKwh" : "einspeisungKwh") : null;
455	      const monate = new Set([...gespeichert.filter((g) => g.messpunktId === mp.id && g.register === r.id).map((g) => g.monat), ...sim.filter((s) => s.vollstaendig).map((s) => s.monat)]);
456	      for (const monat of [...monate].sort()) {
457	        const g = gespeichert.find((x) => x.messpunktId === mp.id && x.register === r.id && x.monat === monat);
458	        const s = sim.find((x) => x.monat === monat && x.vollstaendig);
459	        if (g) zeilen.push({ id: g.id, monat, messpunktId: mp.id, zaehlernummer: mp.zaehlernummer, bezeichnung: mp.bezeichnung, register: r.id, registerLabel: r.label, stand: g.stand, menge: g.menge, quelle: g.quelle, geprueft: !!g.geprueft });
460	        else if (s && feld) zeilen.push({ id: null, monat, messpunktId: mp.id, zaehlernummer: mp.zaehlernummer, bezeichnung: mp.bezeichnung, register: r.id, registerLabel: r.label, stand: Math.round(s.ende[feld]), menge: Math.round(s[feld]), quelle: "Messstellenbetreiber (Demo – aus Simulation abgeleitet)", geprueft: false });
461	      }
462	    }
463	  }
464	  return zeilen.sort((x, y) => y.monat.localeCompare(x.monat) || x.zaehlernummer.localeCompare(y.zaehlernummer) || x.register.localeCompare(y.register));
465	}
