550	  const link = `/portal/anlagen/${a.id}?tab=stoerungen`;
551	  const titel = anlass === "behoben" ? `Störung behoben: ${a.name}` : `Störung: ${a.name}`;
552	  const text = `${STOERUNG_SCHWERE[s.schwere]?.label || ""} – ${s.titel}`;
553	  const empfaenger = new Map();
554	  // Kunde und Team: ab Schwere „mittel“ bzw. bei Behebung
555	  if (stufe >= 2 || anlass === "behoben") {
556	    if (a.kundeId) empfaenger.set(a.kundeId, nutzerById(db, a.kundeId));
557	    for (const m of (db.mitgliedschaften || []).filter((x) => x.organisationId && x.organisationId === a.organisationId)) empfaenger.set(m.nutzerId, nutzerById(db, m.nutzerId));
558	  }
559	  // Betrieb: zuständige Person bzw. alle Backoffice-Konten mit Leserecht „Anlagen“
560	  if (anlass === "neu") {
561	    const z = s.zustaendigId ? nutzerById(db, s.zustaendigId) : null;
562	    const bo = z ? [z] : db.nutzer.filter((u) => u.aktiv && u.rollen.includes("admin") && darfLesen(u, "anlagen"));
563	    for (const u of bo) empfaenger.set(u.id, u);
564	  }
565	  for (const u of empfaenger.values()) {
566	    if (!u) continue;
567	    benachrichtigen(db, u, { art: "stoerung", titel, text, link, objektArt: "anlage", objektId: a.id }, {
