657	export async function stoerungAktion(n, id, daten = {}) {
658	  angemeldet(n);
659	  return aendernBereit((db) => {
660	    const s = db.anlagen.stoerungen.find((x) => x.id === v.kennung(id));
661	    if (!s) throw nichtGefunden("Störung nicht gefunden.");
662	    const a = anlageLaden(db, n, s.anlageId);
663	    const zg = zugriff(db, n, a);
664	    const t = jetzt();
665	    const aktion = daten.aktion;
666	    const wer = nameVon(db, n.id);
667	    if (aktion === "kommentar") {
668	      const ok = zg === "backoffice" ? boSchreiben(n) : zg === "kunde" || zg === "team-schreiben";
669	      if (!ok) throw verboten("Sie können diese Störung nur ansehen.");
670	      const text = v.mehrzeilig(daten.text, 2000);
671	      v.pflicht(text.length >= 2, "Bitte geben Sie einen Kommentar ein.");
672	      s.kommentare = s.kommentare || [];
673	      if (s.kommentare.length >= 200) throw konflikt("Zu viele Kommentare an dieser Störung.");
674	      const internK = zg === "backoffice" && v.wahr(daten.intern);
675	      s.kommentare.push({ id: neueId("KO"), von: n.id, vonName: wer, backoffice: zg === "backoffice", am: t, text, intern: internK });
676	      // Kundenkommentar → zuständige Person bzw. Betrieb informieren (ohne E-Mail-Inhalt)
677	      if (zg !== "backoffice") {
678	        const z = s.zustaendigId ? nutzerById(db, s.zustaendigId) : null;
679	        const bo = z ? [z] : db.nutzer.filter((u) => u.aktiv && u.rollen.includes("admin") && darfSchreiben(u, "anlagen"));
680	        for (const u of bo) benachrichtigen(db, u, { art: "stoerung", titel: `Kommentar zur Störung: ${a.name}`, text: `${wer}: ${text.slice(0, 160)}`, link: `/portal/anlagen/${a.id}?tab=stoerungen`, objektArt: "anlage", objektId: a.id }, { mail: false });
681	      }
682	    } else {
683	      if (!boSchreiben(n)) throw verboten(zg === "backoffice" ? "Ihre Backoffice-Rolle erlaubt im Bereich „Anlagen & Monitoring“ kein Schreiben." : "Störungen quittiert und bearbeitet der Betrieb von ÖkoInvest.");
684	      if (aktion === "quittieren") {
685	        if (s.quittiertAm) throw konflikt("Die Störung ist bereits quittiert.");
686	        s.quittiertAm = t;
687	        s.quittiertVon = n.id;
688	        if (s.status === "offen") s.status = "in_arbeit";
689	        if (!s.zustaendigId) s.zustaendigId = n.id;
690	        s.verlauf.push({ am: t, text: `Quittiert von ${wer}` });
691	      } else if (aktion === "status") {
692	        const neu = v.auswahl(daten.status, STOERUNG_STATUS, "");
693	        if (!neu) throw ungueltig("Unbekannter Status.");
694	        if (neu === s.status) throw konflikt("Die Störung hat diesen Status bereits.");
695	        s.status = neu;
696	        if (neu === "behoben") {
697	          s.behobenAm = t;
698	          if (!s.quittiertAm) {
699	            s.quittiertAm = t;
700	            s.quittiertVon = n.id;
701	          }
702	          stoerungMelden(db, s, "behoben");
703	        } else s.behobenAm = null;
704	        s.verlauf.push({ am: t, text: `Status: ${STOERUNG_STATUS[neu].label} (${wer})${daten.text ? ` – ${v.text(daten.text, 200)}` : ""}` });
705	      } else if (aktion === "zuweisen") {
706	        const zid = v.kennung(daten.zustaendigId);
707	        const z = zid ? nutzerById(db, zid) : null;
708	        if (zid && !(z && z.aktiv && z.rollen.includes("admin") && darfLesen(z, "anlagen"))) throw ungueltig("Zuständig kann nur ein Backoffice-Konto mit Zugriff auf Anlagen sein.");
709	        s.zustaendigId = z?.id || null;
710	        s.verlauf.push({ am: t, text: z ? `Zugewiesen: ${nameVon(db, z.id)}` : "Zuweisung entfernt" });
711	        if (z && z.id !== n.id) benachrichtigen(db, z, { art: "stoerung", titel: `Störung zugewiesen: ${a.name}`, text: s.titel, link: `/portal/anlagen/${a.id}?tab=stoerungen`, objektArt: "anlage", objektId: a.id }, { mail: false });
712	      } else if (aktion === "schwere") {
