export const PRUEF_ARTEN = {
  wiederkehrend: "Wiederkehrende Prüfung (E-Check / DGUV V3 / ESV / NIV)",
  erstpruefung: "Erstprüfung / Inbetriebnahmeprüfung (IEC 62446-1)",
