                </li>
              ))}
            </ul>
          )}
          {s && <div className="flex flex-wrap gap-3 border-t border-ink-100 px-5 py-4 md:px-6"><NeuerAuftrag anlageId={a.id} /><NeuerVersicherungsfall anlageId={a.id} /></div>}
        </Karte>
      </div>
    </>
  );
}

