// src/lib/plattform/energie/lieferwechsel.js
//
// Energiebeschaffung – Nachlauf nach dem Zuschlag (reine Regeln, Node-testbar): Lieferantenwechsel bis zum Lieferbeginn,
// Aktivierung des neuen Vertrags (danach laufende Wechselanalyse und Kündigungsfristen wie bei jedem Vertrag).
// Frappe: plattform/energie_kern.py (Abschnitt „Lieferantenwechsel“).
//
// Ablauf je Vertrag aus Zuschlag (Status „neu“):
//   1. daten       – Kundendaten und Lokations-ID (DE: MaLo-ID, AT: Zählpunktnummer) an den neuen Versorger übermittelt
//   2. kuendigung  – Altvertrag gekündigt, Kündigungsbestätigung liegt vor (entfällt ohne Vorvertrag)
//   3. anmeldung   – Lieferbeginn vom neuen Versorger bzw. Netzbetreiber bestätigt
//   → ab Lieferbeginn (Stichtag erreicht, alle Schritte erledigt) wird der Vertrag „aktiv“, der Vorvertrag „beendet“.
// Hinweis: DE – Lieferantenwechsel nach GPKE (BNetzA-Festlegung), der neue Lieferant meldet an; AT – Wechsel über den
// Netzbetreiber nach Wechselverordnung (E-Control). Fristen im Einzelfall beim Versorger bestätigen lassen.

export const WECHSEL_SCHRITTE = [
  { id: "daten", label: "Kundendaten und Lokations-ID an den neuen Versorger übermittelt", hinweis: "DE: Marktlokations-ID (MaLo), AT: Zählpunktnummer; Firmenname, Anschrift, Jahresmenge" },
  { id: "kuendigung", label: "Altvertrag gekündigt – Kündigungsbestätigung liegt vor", hinweis: "Kündigung fristgerecht zum Tag vor Lieferbeginn; Bestätigung ablegen", nurMitVorvertrag: true },
  { id: "anmeldung", label: "Lieferbeginn vom Versorger bzw. Netzbetreiber bestätigt", hinweis: "DE: Anmeldung durch den neuen Lieferanten (GPKE), AT: Wechsel über den Netzbetreiber" },
];
export const WECHSEL_SCHRITT_IDS = WECHSEL_SCHRITTE.map((s) => s.id);
/** Warnschwelle vor Lieferbeginn, wenn der Wechsel noch nicht vollständig bestätigt ist */
export const WECHSEL_WARN_TAGE = 21;

export class WechselFehler extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

const tage = (von, bis) => Math.round((Date.parse(`${bis}T00:00:00Z`) - Date.parse(`${von}T00:00:00Z`)) / 86400e3);

/** Schritte, die für diesen Vertrag gelten */
export const schritteFuer = (vertrag) => WECHSEL_SCHRITTE.filter((s) => !s.nurMitVorvertrag || !!vertrag?.vorvertragId);

/**
 * Stand des Lieferantenwechsels: { schritte:[{id,label,hinweis,erledigtAm,notiz}], offen, vollstaendig, tageBisBeginn,
 * warnung (≤ 21 Tage und nicht vollständig), ueberfaellig (Beginn erreicht, nicht vollständig), aktivierbar }
 */
export function wechselStatus(vertrag, heute) {
  const w = vertrag?.wechsel || {};
  const schritte = schritteFuer(vertrag).map((s) => ({ ...s, erledigtAm: w[s.id]?.am || null, notiz: w[s.id]?.notiz || "" }));
  const offen = schritte.filter((s) => !s.erledigtAm).map((s) => s.id);
  const beginn = String(vertrag?.beginn || "").slice(0, 10);
  const t = /^\d{4}-\d{2}-\d{2}$/.test(beginn) ? tage(heute, beginn) : null;
  const vollstaendig = offen.length === 0;
  return {
    schritte, offen, vollstaendig, tageBisBeginn: t,
    warnung: vertrag?.status === "neu" && !vollstaendig && t !== null && t <= WECHSEL_WARN_TAGE && t >= 0,
    ueberfaellig: vertrag?.status === "neu" && !vollstaendig && t !== null && t < 0,
    aktivierbar: vertrag?.status === "neu" && vollstaendig && t !== null && t <= 0,
  };
}

/** Schritt als erledigt erfassen (bzw. mit zuruecksetzen=true zurücknehmen) – liefert das neue wechsel-Objekt */
export function schrittSetzen(vertrag, schrittId, { datum, notiz = "", zuruecksetzen = false } = {}, heute) {
  if (vertrag?.status !== "neu") throw new WechselFehler(409, "Der Lieferantenwechsel ist nur für neue Verträge aus einem Zuschlag zu pflegen.");
  const s = schritteFuer(vertrag).find((x) => x.id === schrittId);
  if (!s) throw new WechselFehler(422, "Unbekannter Schritt.");
  const w = { ...(vertrag.wechsel || {}) };
  if (zuruecksetzen) {
    delete w[s.id];
    return w;
  }
  const d = String(datum || heute);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) throw new WechselFehler(422, "Bitte ein gültiges Datum angeben.");
  if (d > heute) throw new WechselFehler(422, "Das Datum darf nicht in der Zukunft liegen.");
  if (s.id === "anmeldung" && !w.daten) throw new WechselFehler(409, "Zuerst die Übermittlung der Kundendaten an den Versorger erfassen.");
  w[s.id] = { am: d, notiz: String(notiz || "").slice(0, 300) };
  return w;
}

/** Verträge, die in Wechselanalyse und Fristen-Alarm gehören: laufend (aktiv) oder gekündigt – egal ob aus Zuschlag */
export const analyseRelevant = (vt) => ["aktiv", "gekuendigt"].includes(vt?.status);

