function profilfaktorAus(kurve, zone, von, peakAnteil) {
  const bis = zwoelfMonate(von);
  const base = terminPreisZeitraum(kurve, zone, von, bis, "base");
  const peak = terminPreisZeitraum(kurve, zone, von, bis, "peak");
