import { route } from "@/lib/plattform/server/route";
import { energieBackend } from "@/lib/plattform/backend/energie";

export const GET = route({ admin: true }, async ({ nutzer, params }) => ({ ok: true, kunde: await energieBackend().energieKunde(nutzer, params.id) }));
export const POST = route({ admin: true }, async ({ nutzer, params, body }) => ({
  ok: true,
  vertrag: await energieBackend().energieVertragSpeichern(nutzer, { id: body.vertragId || null, kundeId: params.id, daten: body.daten && typeof body.daten === "object" ? body.daten : {} }),
}));

// POST /api/admin/energie/kunden/[id]/lieferwechsel – { vertragId, schritt: daten|kuendigung|anmeldung, datum?, notiz?, zuruecksetzen? }
// Nachlauf nach Zuschlag: Lieferantenwechsel dokumentieren; vollständig + Lieferbeginn erreicht → Vertrag aktiv, Vorvertrag beendet.
import { route } from "@/lib/plattform/server/route";
import { energieBackend } from "@/lib/plattform/backend/energie";

export const POST = route({ admin: true }, async ({ nutzer, body }) => ({ ok: true, vertrag: await energieBackend().energieLieferwechsel(nutzer, body.vertragId, { schritt: body.schritt, datum: body.datum, notiz: body.notiz, zuruecksetzen: !!body.zuruecksetzen }) }));

