"use client";

// Energiebeschaffung – Nachlauf nach Zuschlag: Lieferantenwechsel je neuem Vertrag dokumentieren (Backoffice).
// Schritte und Aktivierung zum Lieferbeginn prüft der Server (/api/admin/energie/kunden/[id]/lieferwechsel).

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Check, RotateCcw } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { senden } from "@/lib/plattform/client";

export default function Lieferwechsel({ kundeId, vertrag, schreiben = false }) {
  const router = useRouter();
  const [datum, setDatum] = useState(new Date().toISOString().slice(0, 10));
  const [notiz, setNotiz] = useState("");
  const [laeuft, setLaeuft] = useState("");
  const [fehler, setFehler] = useState("");
  const [ok, setOk] = useState("");
  const st = vertrag.wechselStand;
  if (!st) return null;
  async function setzen(schritt, zuruecksetzen = false) {
    setLaeuft(schritt);
    setFehler("");
    setOk("");
    try {
      const r = await senden(`/api/admin/energie/kunden/${kundeId}/lieferwechsel`, { body: { vertragId: vertrag.id, schritt, datum, notiz, zuruecksetzen } });
      setOk(r.vertrag?.aktiviert ? "Wechsel vollständig – der Vertrag ist ab Lieferbeginn aktiv, der Vorvertrag beendet." : zuruecksetzen ? "Zurückgenommen." : "Gespeichert.");
      setNotiz("");
      router.refresh();
    } catch (e) {
      setFehler(e.message);
    } finally {
      setLaeuft("");
    }
  }
  return (
    <div className={cn("rounded-2xl p-4 ring-1 ring-inset", st.ueberfaellig ? "bg-red-50 ring-red-200" : st.warnung ? "bg-sun-300/20 ring-sun-400/40" : "bg-sand-50 ring-ink-200/60")}>
      <p className="font-semibold text-ink-900">Lieferantenwechsel zu {vertrag.lieferantName || vertrag.lieferant}</p>
      <p className="text-[13px] text-ink-600">
        Lieferbeginn {String(vertrag.beginn).split("-").reverse().join(".")}
        {st.tageBisBeginn !== null ? (st.tageBisBeginn >= 0 ? ` · in ${st.tageBisBeginn} Tagen` : ` · seit ${-st.tageBisBeginn} Tagen`) : ""}
        {st.ueberfaellig ? " · Wechsel noch nicht bestätigt" : st.vollstaendig ? " · alle Schritte bestätigt – wird zum Lieferbeginn aktiv" : ""}
      </p>
      <ol className="mt-3 space-y-2">
        {st.schritte.map((s, i) => (
          <li key={s.id} className="flex flex-wrap items-start justify-between gap-2 rounded-xl bg-white px-3 py-2.5 ring-1 ring-inset ring-ink-200/70">
            <div className="min-w-0">
              <p className="text-[13.5px] font-semibold text-ink-900">{i + 1}. {s.label}</p>
              <p className="text-[12px] text-ink-500">{s.erledigtAm ? `erledigt am ${s.erledigtAm.split("-").reverse().join(".")}${s.notiz ? ` · ${s.notiz}` : ""}` : s.hinweis}</p>
            </div>
            {schreiben && (s.erledigtAm ? (
              <button type="button" disabled={!!laeuft} onClick={() => setzen(s.id, true)} className="inline-flex h-8 items-center gap-1 rounded-full px-3 text-[12.5px] font-semibold text-ink-600 ring-1 ring-inset ring-ink-200 hover:bg-ink-50 disabled:opacity-50"><RotateCcw aria-hidden="true" className="h-3.5 w-3.5" />Zurücknehmen</button>
            ) : (
              <button type="button" disabled={!!laeuft} onClick={() => setzen(s.id)} className="inline-flex h-8 items-center gap-1 rounded-full bg-ov-600 px-3 text-[12.5px] font-semibold text-white hover:bg-ov-700 disabled:opacity-50"><Check aria-hidden="true" className="h-3.5 w-3.5" />{laeuft === s.id ? "…" : "Erledigt"}</button>
            ))}
          </li>
        ))}
      </ol>
      {schreiben && !st.vollstaendig && (
        <div className="mt-3 flex flex-wrap gap-2 text-[13px]">
          <label className="font-semibold text-ink-700">Datum<input type="date" value={datum} max={new Date().toISOString().slice(0, 10)} onChange={(e) => setDatum(e.target.value)} className="ml-2 h-9 rounded-xl border border-ink-200 bg-white px-2" /></label>
          <label className="font-semibold text-ink-700">Notiz<input value={notiz} maxLength={300} onChange={(e) => setNotiz(e.target.value)} placeholder="z. B. Bestätigung Versorger vom …" className="ml-2 h-9 w-56 rounded-xl border border-ink-200 bg-white px-2" /></label>
        </div>
      )}
      {fehler && <p role="alert" className="mt-2 text-[13px] font-semibold text-red-700">{fehler}</p>}
      {ok && <p role="status" className="mt-2 text-[13px] font-semibold text-ov-700">{ok}</p>}
    </div>
  );
}

