def plan_vorschlag(anlage, vorhandene=()):
	vorlage = WARTUNG_VORLAGEN.get(anlage.get("land")) or WARTUNG_VORLAGEN["DE"]
	mit_speicher = anlage.get("typ") == "speicher" or float(anlage.get("speicherKwh") or 0) > 0
