		"beschreibung": v.mehrzeilig(d.get("beschreibung"), 2000), "termin": termin[:16] if _datum(termin) else "", "kosten_eur": v.zahl(d.get("kostenEur"), 0, 10000000), "bestellnummer": v.text(d.get("bestellnummer"), 60),
