		"schaden_eur": v.zahl(d.get("schadenEur"), 0, 1e9), "selbstbehalt_eur": v.zahl(d.get("selbstbehaltEur"), 0, 1e8), "ertragsausfall_eur": v.zahl(d.get("ertragsausfallEur"), 0, 1e9), "bemerkung": v.mehrzeilig(d.get("bemerkung"), 1000),
