		"firma": p.firma or "", "norm": p.norm or "", "einstrahlungWm2": flt(p.einstrahlung_wm2) or None, "ergebnis": p.ergebnis, "ergebnisLabel": bk.PRUEF_ERGEBNIS.get(p.ergebnis, p.ergebnis),
