WECHSEL_SCHRITTE = [
	{"id": "daten", "label": "Kundendaten und Lokations-ID an den neuen Versorger übermittelt", "hinweis": "DE: Marktlokations-ID (MaLo), AT: Zählpunktnummer; Firmenname, Anschrift, Jahresmenge"},
	{"id": "kuendigung", "label": "Altvertrag gekündigt – Kündigungsbestätigung liegt vor", "hinweis": "Kündigung fristgerecht zum Tag vor Lieferbeginn; Bestätigung ablegen", "nurMitVorvertrag": True},
	{"id": "anmeldung", "label": "Lieferbeginn vom Versorger bzw. Netzbetreiber bestätigt", "hinweis": "DE: Anmeldung durch den neuen Lieferanten (GPKE), AT: Wechsel über den Netzbetreiber"},
]
WECHSEL_WARN_TAGE = 21


class WechselFehler(Exception):
	def __init__(self, status, text):
		super().__init__(text)
		self.status = status
		self.text = text


def wechsel_schritte_fuer(vorvertrag_id):
	return [s for s in WECHSEL_SCHRITTE if not s.get("nurMitVorvertrag") or vorvertrag_id]


def wechsel_status(status, beginn, vorvertrag_id, wechsel, heute):
	w = wechsel or {}
	schritte = [{**s, "erledigtAm": (w.get(s["id"]) or {}).get("am"), "notiz": (w.get(s["id"]) or {}).get("notiz", "")} for s in wechsel_schritte_fuer(vorvertrag_id)]
	offen = [s["id"] for s in schritte if not s["erledigtAm"]]
	b = str(beginn or "")[:10]
	t = tage_zwischen(heute, b) if len(b) == 10 else None
	voll = not offen
	neu = status == "neu"
	return {
		"schritte": schritte, "offen": offen, "vollstaendig": voll, "tageBisBeginn": t,
		"warnung": neu and not voll and t is not None and 0 <= t <= WECHSEL_WARN_TAGE,
		"ueberfaellig": neu and not voll and t is not None and t < 0,
		"aktivierbar": neu and voll and t is not None and t <= 0,
	}


def wechsel_schritt_setzen(status, vorvertrag_id, wechsel, schritt, datum, notiz, zuruecksetzen, heute):
	if status != "neu":
		raise WechselFehler(409, "Der Lieferantenwechsel ist nur für neue Verträge aus einem Zuschlag zu pflegen.")
	s = next((x for x in wechsel_schritte_fuer(vorvertrag_id) if x["id"] == schritt), None)
	if not s:
		raise WechselFehler(422, "Unbekannter Schritt.")
	w = dict(wechsel or {})
	if zuruecksetzen:
		w.pop(s["id"], None)
		return w
	d = str(datum or heute)[:10]
	if len(d) != 10 or d[4] != "-" or d[7] != "-":
		raise WechselFehler(422, "Bitte ein gültiges Datum angeben.")
	if d > heute:
		raise WechselFehler(422, "Das Datum darf nicht in der Zukunft liegen.")
	if s["id"] == "anmeldung" and not w.get("daten"):
		raise WechselFehler(409, "Zuerst die Übermittlung der Kundendaten an den Versorger erfassen.")
	w[s["id"]] = {"am": d, "notiz": str(notiz or "")[:300]}
	return w


def analyse_relevant(status):
	"""Laufend oder gekündigt – egal ob aus Zuschlag (Wechselanalyse und Fristen-Alarm)."""
	return status in ("aktiv", "gekuendigt")
